import { onAuthStateChanged } from 'https://www.gstatic.com/firebasejs/12.16.0/firebase-auth.js';
import { auth } from './firebase-client.js';

const ADMIN_EMAIL='info@9works.kr';
const ACCESS_KEY='nw:phyto:client-access:v1';
const ACCESS_TTL=12*60*60*1000;
const EXPECTED_HASH='3a42fb039c65ccac7a3b50fddb88e8b6e5aa333f119fb4727f89c207b5ada496';

const q=(s,r=document)=>r.querySelector(s);
const qa=(s,r=document)=>Array.from(r.querySelectorAll(s));
const set=(s,t,r=document)=>{const n=q(s,r);if(n)n.textContent=t};

function readGrant(){try{const v=JSON.parse(localStorage.getItem(ACCESS_KEY)||'null');return !!(v&&Number(v.expiresAt)>Date.now())}catch{return false}}
function saveGrant(){try{localStorage.setItem(ACCESS_KEY,JSON.stringify({expiresAt:Date.now()+ACCESS_TTL}))}catch{}}
function unlock(){document.body.classList.remove('nw-phyto-locked');q('.nw-phyto-gate')?.remove()}
async function hashText(value){const d=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value));return Array.from(new Uint8Array(d)).map(b=>b.toString(16).padStart(2,'0')).join('')}
function gateMarkup(){return `<div class="nw-phyto-gate" role="dialog" aria-modal="true"><div class="nw-phyto-gate__card"><div class="nw-phyto-gate__brand"><img src="/assets/logo-nineworks.svg" alt="NINEWORKS"><span>PRIVATE CLIENT PORTAL</span></div><p class="nw-phyto-gate__kicker">PHYTOREVOLUTION · GOSRAN</p><h1 class="nw-phyto-gate__title">프로젝트 전용 페이지</h1><p class="nw-phyto-gate__desc">파이토레볼루션 대표님께 공유드리는 전용 프로젝트 공간입니다. 계약, 견적, 진행 현황과 정산 관련 문서를 한곳에서 확인하실 수 있습니다.</p><div class="nw-phyto-gate__onboarding"><div class="nw-phyto-gate__step"><b>01</b><span>현재 계약 및 프로젝트 세팅 단계의 자료를 확인합니다.</span></div><div class="nw-phyto-gate__step"><b>02</b><span>계약서 초안과 견적 내용을 확인한 뒤 계약 확인을 전달합니다.</span></div><div class="nw-phyto-gate__step"><b>03</b><span>브랜드 아이덴티티, 기본형 가이드라인, 패키지 및 기본형 상세페이지 진행 상태가 순차적으로 업데이트됩니다.</span></div></div><form class="nw-phyto-gate__form" data-phyto-gate-form><input class="nw-phyto-gate__input" data-phyto-gate-input type="password" autocomplete="current-password" placeholder="프로젝트 비밀번호" required><button class="nw-phyto-gate__button" type="submit">프로젝트 입장</button></form><div class="nw-phyto-gate__error" data-phyto-gate-error></div><div class="nw-phyto-gate__meta"><span>인증 상태는 이 브라우저에서 12시간 유지됩니다.</span><span>문의 · info@9works.kr</span></div></div></div>`}
function renderForm(){q('.nw-phyto-gate')?.remove();document.body.insertAdjacentHTML('beforeend',gateMarkup());const f=q('[data-phyto-gate-form]'),i=q('[data-phyto-gate-input]'),e=q('[data-phyto-gate-error]');f?.addEventListener('submit',async ev=>{ev.preventDefault();const v=String(i?.value||'').trim();if(!v)return;try{if(await hashText(v)===EXPECTED_HASH){saveGrant();unlock();return}}catch{}if(e)e.textContent='비밀번호가 일치하지 않습니다. 다시 확인해 주세요.';if(i){i.value='';i.focus()}});setTimeout(()=>i?.focus(),50)}

function injectStyle(){if(q('[data-phyto-scope-safe]'))return;const s=document.createElement('style');s.dataset.phytoScopeSafe='true';s.textContent=`.nw-phyto-scope-safe .progress-line{grid-template-columns:repeat(6,minmax(0,1fr))}.phyto-update-panel{margin-top:18px;border:1px solid #d5d5d0;background:#fff}.phyto-update-head{display:flex;justify-content:space-between;gap:16px;align-items:center;min-height:42px;padding:0 16px;border-bottom:1px solid #d5d5d0}.phyto-update-head h2{margin:0;font-size:10.5px;font-weight:500}.phyto-update-head span{color:#999;font-size:9px}.phyto-update-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.phyto-update-item{padding:14px 16px;border-right:1px solid #dededa;border-bottom:1px solid #dededa}.phyto-update-item:nth-child(even){border-right:0}.phyto-update-item:nth-last-child(-n+2){border-bottom:0}.phyto-update-item span{display:block;margin-bottom:6px;color:#999;font-size:8.5px}.phyto-update-item strong{display:block;font-size:11.5px;font-weight:500;line-height:1.55}.phyto-update-item p{margin:5px 0 0;color:#777;font-size:9.5px;line-height:1.6}.phyto-contract-note{margin:16px 0 0;padding:14px 16px;border:1px solid #cfcfca;background:#fff}.phyto-contract-note b{display:block;margin-bottom:7px;font-size:9px}.phyto-contract-note p{margin:0!important;color:#555551;font-size:10.5px!important;line-height:1.75!important}.phyto-contract-note p+p{margin-top:7px!important}@media(max-width:720px){.nw-phyto-scope-safe .progress-line{grid-template-columns:1fr}.phyto-update-grid{grid-template-columns:1fr}.phyto-update-item{border-right:0;border-bottom:1px solid #dededa!important}.phyto-update-item:last-child{border-bottom:0!important}}`;document.head.appendChild(s)}

function applyDashboard(){document.body.classList.add('nw-phyto-scope-safe');injectStyle();set('.brand-row > span:last-child','고스란 · 브랜드 아이덴티티 · 기본 가이드라인 · 패키지 · 기본형 상세페이지');set('.client-desc','파이토레볼루션의 고스란 브랜드 프로젝트 전용 대시보드입니다. 브랜드 아이덴티티 정립, 기본형 가이드라인, 패키지 및 기본형 상세페이지 디자인과 정부지원사업 일정·진행 상태를 한 화면에서 확인할 수 있습니다.');const sv=qa('.summary-value');if(sv[3])sv[3].innerHTML='고스란<small>브랜드 아이덴티티 · 가이드라인 · 패키지 · 기본형 상세페이지</small>';const pc=q('.progress-copy');if(pc)pc.innerHTML='<span>현재 단계 · 자료 수령 및 디자인 착수 준비</span><span>9월 9일 1차 시안 목표</span>';const pl=q('.progress-line');if(pl)pl.innerHTML=`<div class="progress-step is-active"><div class="progress-dot">01</div><div><strong>자료·계약 세팅</strong><p>계약/지원사업 자료 확인</p></div></div><div class="progress-step"><div class="progress-dot">02</div><div><strong>브랜드 아이덴티티</strong><p>로고·핵심 시각체계 정립</p></div></div><div class="progress-step"><div class="progress-dot">03</div><div><strong>기본 가이드라인</strong><p>기본 사용 규칙 정리</p></div></div><div class="progress-step"><div class="progress-dot">04</div><div><strong>패키지·기본형 상세페이지</strong><p>제품 적용 디자인 진행</p></div></div><div class="progress-step"><div class="progress-dot">05</div><div><strong>정산·최종 납품</strong><p>9/20 행정자료 및 결과 정리</p></div></div><div class="progress-step"><div class="progress-dot">06</div><div><strong>유지보수</strong><p>계약 종료 후 2개월</p></div></div>`;const rows=qa('.compact-row');if(rows[2]){set('span','SCOPE',rows[2]);set('strong','브랜드 아이덴티티 · 기본형 가이드라인 · 패키지 · 기본형 상세페이지 디자인',rows[2])}const tl=q('.timeline-list');if(tl)tl.innerHTML=`<div class="timeline-row is-active"><div class="timeline-no">01</div><div><strong>자료 수령 및 계약 반영</strong><p>세금계산서·사업자등록증·사본·통장사본 등 지원사업 서류 확인</p></div></div><div class="timeline-row"><div class="timeline-no">02</div><div><strong>9월 9일 · 1차 디자인 확인</strong><p>고스란 및 파이토레볼루션 로고 방향을 포함해 출원 준비가 가능하도록 우선 진행</p></div></div><div class="timeline-row"><div class="timeline-no">03</div><div><strong>브랜드 가이드 · 패키지 · 기본형 상세페이지</strong><p>승인 방향을 기준으로 주요 적용물 디자인을 순차 개발</p></div></div><div class="timeline-row"><div class="timeline-no">04</div><div><strong>9월 20일 · 지원사업 행정 마감</strong><p>용역결과보고서 및 정산에 필요한 자료 전달을 우선 완료</p></div></div><div class="timeline-row"><div class="timeline-no">05</div><div><strong>10월 27일 · 계약 원안 종료</strong><p>지원사업 행정 일정과 별개로 본 프로젝트 계약기간은 원안 기준 유지</p></div></div>`;if(!q('.phyto-update-panel'))q('.progress-panel')?.insertAdjacentHTML('afterend',`<section class="phyto-update-panel"><div class="phyto-update-head"><h2>PROJECT UPDATE · 2026.08.28</h2><span>CLIENT REQUEST / CONFIRMED</span></div><div class="phyto-update-grid"><div class="phyto-update-item"><span>09.09 · DESIGN</span><strong>고스란 / 파이토레볼루션 로고 디자인 우선 진행</strong><p>특허·출원 비용 신청 일정에 맞춰 1차 확인 가능한 수준으로 빠르게 진행합니다.</p></div><div class="phyto-update-item"><span>09.20 · ADMIN</span><strong>정부지원사업 용역결과보고서 및 정산자료 전달</strong><p>지원사업 행정 마감을 위해 9월 20일까지 필요한 결과·증빙 자료를 우선 정리합니다.</p></div><div class="phyto-update-item"><span>CONTRACT</span><strong>본 계약기간은 2026.10.27까지 유지</strong><p>지원사업비 종료 일정과 별개로 계약기간 원안은 유지합니다.</p></div><div class="phyto-update-item"><span>SAMPLE COST</span><strong>간단 단상자 샘플은 10만원 내 지원 예정</strong><p>대형 박스·싸바리 등 30만원 이상 제작비 발생 시 사전 협의 후 별도 비용으로 진행합니다.</p></div></div></section>`) }

function clause(title){return qa('.clause').find(c=>q('h2',c)?.textContent.trim()===title)}
function applyContract(){injectStyle();set('.doc-head h1 span','파이토레볼루션 · 고스란 브랜드 아이덴티티 · 가이드라인 · 패키지 · 기본형 상세페이지 디자인 프로젝트');set('.doc-intro','파이토레볼루션이 운영하는 고스란 브랜드의 아이덴티티 정립, 기본형 브랜드 가이드라인 구축, 패키지 및 기본형 상세페이지 디자인을 포함한 프로젝트의 업무 범위, 기간, 금액 및 양 당사자의 기본 권리·의무를 확인하기 위한 계약서 초안입니다.');const ov=qa('.overview-value');if(ov[0])ov[0].textContent='고스란 브랜드 아이덴티티 · 기본형 가이드라인 · 패키지 · 기본형 상세페이지 디자인 프로젝트';const s=clause('용역 범위 및 세부 작업 내용');if(s)q('div:last-child',s).innerHTML=`<h2>용역 범위 및 세부 작업 내용</h2><p>본 계약에 포함되는 기본 용역 범위는 다음과 같다.</p><div class="scope-table"><div class="scope-row"><b>Brand Direction</b><span>고스란 브랜드의 방향, 핵심 메시지와 디자인 기준 정리</span></div><div class="scope-row"><b>Brand Identity</b><span>고스란 및 파이토레볼루션 로고 체계, 컬러, 타이포그래피, 기본 그래픽 및 이미지 방향을 포함한 핵심 시각 아이덴티티 정립</span></div><div class="scope-row"><b>Basic Guideline</b><span>정립된 브랜드 아이덴티티의 기본 사용 규칙과 주요 시각 기준을 문서화한 기본형 브랜드 가이드라인 구축</span></div><div class="scope-row"><b>Package Design</b><span>확정된 브랜드 아이덴티티와 제공된 제품 정보·칼선을 기준으로 주요 제품 패키지 디자인 개발 및 적용</span></div><div class="scope-row"><b>Basic Detail Page</b><span>확정된 브랜드·제품 디자인 방향을 기준으로 주요 제품의 기본형 상세페이지 디자인 구성 및 적용</span></div><div class="scope-row"><b>Final Delivery</b><span>최종 검수, 가이드라인·패키지·기본형 상세페이지 납품 대상 데이터 및 정부지원사업 결과자료 정리</span></div><div class="scope-row"><b>Maintenance</b><span>계약 종료 후 2개월간 상호 합의된 범위 내 유지보수 진행</span></div></div><p>세부 패키지 품목, 기본형 상세페이지 적용 범위, 규격과 우선순위는 갑이 제공하는 제품 정보 및 프로젝트 진행 과정에서 상호 확인된 범위를 기준으로 진행한다.</p><div class="phyto-contract-note"><b>지원사업 일정 및 샘플 제작비 안내</b><p>정부지원사업 행정 일정상 2026년 9월 20일까지 용역결과보고서 및 정산 관련 자료를 우선 정리·전달하는 것을 목표로 한다. 다만 본 계약의 용역기간은 원안대로 2026년 10월 27일까지 유지한다.</p><p>간단한 단상자 샘플 제작은 10만원 이내 범위에서 을이 지원할 예정이며, 대형 박스·싸바리 등 제작 방식으로 샘플 제작비가 30만원 이상 발생하는 경우 사전 협의 후 별도 비용으로 진행한다.</p></div>`;const d=clause('산출물');if(d)q('div:last-child',d).innerHTML=`<h2>산출물</h2><p>산출물은 본 계약의 용역 범위와 프로젝트 진행 과정에서 상호 확인된 적용 항목을 기준으로 한다.</p><ul><li data-no="1)">브랜드 방향 및 핵심 메시지 정리 자료</li><li data-no="2)">고스란 및 파이토레볼루션 브랜드 아이덴티티 핵심 시각 자산 및 디자인 시스템</li><li data-no="3)">기본형 브랜드 가이드라인</li><li data-no="4)">패키지 디자인 적용 결과물</li><li data-no="5)">상호 확정된 제품 범위를 기준으로 한 기본형 상세페이지 디자인 결과물</li><li data-no="6)">최종 검수 후 납품 대상으로 확정된 디자인 데이터와 정부지원사업 용역결과 관련 자료</li></ul>`}

function applyQuote(){const pr=qa('.info .row').find(r=>q('b',r)?.textContent.trim()==='프로젝트');if(pr)set('span','고스란 브랜드 아이덴티티 · 기본형 가이드라인 · 패키지 · 기본형 상세페이지 디자인 프로젝트',pr);set('.sumhead h2','GOSRAN Brand Identity, Package & Basic Detail Page');const s=q('.scope');if(s)s.innerHTML=`<div><b>Brand Direction</b><span>브랜드 방향, 핵심 메시지 및 프로젝트 디자인 기준 정리</span></div><div><b>Brand Identity</b><span>고스란 및 파이토레볼루션 로고 체계, 컬러, 타이포그래피와 주요 시각 아이덴티티 정립</span></div><div><b>Basic Guideline</b><span>정립된 브랜드 아이덴티티의 기본 사용 원칙과 시각 기준 문서화</span></div><div><b>Package Design</b><span>확정 아이덴티티와 제공된 제품 정보·칼선을 기준으로 패키지 디자인 개발</span></div><div><b>Basic Detail Page</b><span>확정된 브랜드·제품 방향을 기준으로 주요 제품 기본형 상세페이지 디자인 구성</span></div><div><b>Final Delivery</b><span>가이드라인, 패키지·기본형 상세페이지 및 정부지원사업 결과자료 정리</span></div><div><b>Maintenance</b><span>계약 종료 후 2개월간 합의된 범위 내 유지보수 진행</span></div>`;const n=qa('.note').find(x=>q('strong',x)?.textContent.trim()==='Scope');if(n)set('span','본 견적은 고스란 브랜드 아이덴티티 정립, 기본형 브랜드 가이드라인 구축, 주요 패키지 및 기본형 상세페이지 디자인 개발과 최종 결과물 정리를 기준으로 하며, 합의된 범위를 벗어나는 추가 품목·규격·제작 업무는 별도 협의합니다.',n)}

function apply(){const p=location.pathname.toLowerCase();if(!p.includes('/client/phyto'))return;if(p.endsWith('/client/phyto/')||p.endsWith('/client/phyto/index.html'))applyDashboard();else if(p.endsWith('/contract.html'))applyContract();else if(p.endsWith('/quote.html'))applyQuote()}
function init(){apply();if(!document.body.classList.contains('nw-phyto-locked'))return;if(readGrant()){unlock();return}if(!auth){renderForm();return}const email=String(auth.currentUser?.email||'').toLowerCase();if(email===ADMIN_EMAIL){unlock();return}let done=false;const timer=setTimeout(()=>{if(!done)renderForm()},1200);const stop=onAuthStateChanged(auth,user=>{if(done)return;done=true;clearTimeout(timer);stop();String(user?.email||'').toLowerCase()===ADMIN_EMAIL?unlock():renderForm()},()=>{if(done)return;done=true;clearTimeout(timer);renderForm()})}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();